defmodule SimpleGrpc.TypespecTest do
  use ExUnit.Case, async: true

  setup_all do
    # Enable docs and debug_info so typespec chunks are preserved in generated bytecode
    old_opts = Code.compiler_options()
    Code.put_compiler_option(:docs, true)
    Code.put_compiler_option(:debug_info, true)

    compiled =
      Code.compile_string("""
      defmodule SimpleGrpc.TypespecTest.Server do
        use SimpleGrpc.Server,
          server_file: "test/fixtures/protos/streaming/streaming_service.proto",
          service: "StreamingService"

        def unary_call(req, _stream), do: %{result: req.message, sequence: req.sequence, is_final: true}
        def server_streaming_call(req, _stream), do: [%{result: req.message, sequence: 1, is_final: true}]
        def client_streaming_call(_req_stream, _stream), do: %{result: "received", sequence: 1, is_final: true}
        def bidirectional_streaming_call(_req_stream, _stream), do: [%{result: "bidi", sequence: 1, is_final: true}]
      end

      defmodule SimpleGrpc.TypespecTest.Client do
        use SimpleGrpc.Client,
          client_file: "test/fixtures/protos/streaming/streaming_service.proto",
          service: "StreamingService"
      end
      """)

    Code.compiler_options(old_opts)

    beam_map = Map.new(compiled)
    {:ok, beam_map: beam_map}
  end

  describe "Message struct typespecs" do
    test "generated message modules expose @type t and @spec new/1", %{beam_map: beam_map} do
      req_mod = SimpleGrpc.TypespecTest.Server.StreamRequest
      req_bin = Map.fetch!(beam_map, req_mod)

      {:ok, types} = Code.Typespec.fetch_types(req_bin)
      type_names = Enum.map(types, fn {kind, {name, _ast, _args}} -> {kind, name} end)

      assert {:type, :t} in type_names
      assert {:type, :attrs} in type_names

      {:ok, specs} = Code.Typespec.fetch_specs(req_bin)
      spec_names = Enum.map(specs, fn {{name, arity}, _ast} -> {name, arity} end)

      assert {:new, 0} in spec_names or {:new, 1} in spec_names
    end

    test "generates typed struct instances with .new/1" do
      req_mod = SimpleGrpc.TypespecTest.Server.StreamRequest
      req = apply(req_mod, :new, [[message: "hello typed world", sequence: 42]])
      assert req.__struct__ == req_mod
      assert req.message == "hello typed world"
      assert req.sequence == 42
    end
  end

  describe "Client RPC specs" do
    test "generated client exposes @spec for snake, orig, and bang RPC variants", %{
      beam_map: beam_map
    } do
      client_mod = SimpleGrpc.TypespecTest.Client
      client_bin = Map.fetch!(beam_map, client_mod)

      {:ok, specs} = Code.Typespec.fetch_specs(client_bin)
      spec_signatures = Enum.map(specs, fn {{name, arity}, _ast} -> {name, arity} end)

      assert {:unary_call, 3} in spec_signatures or {:unary_call, 2} in spec_signatures
      assert {:UnaryCall, 3} in spec_signatures or {:UnaryCall, 2} in spec_signatures
      assert {:unary_call!, 3} in spec_signatures or {:unary_call!, 2} in spec_signatures
      assert {:UnaryCall!, 3} in spec_signatures or {:UnaryCall!, 2} in spec_signatures

      assert {:server_streaming_call, 3} in spec_signatures or
               {:server_streaming_call, 2} in spec_signatures

      assert {:grpc_path, 1} in spec_signatures
      assert {:build_request, 1} in spec_signatures or {:build_request, 2} in spec_signatures
      assert {:build_response, 1} in spec_signatures or {:build_response, 2} in spec_signatures
    end
  end

  describe "Server RPC callbacks" do
    test "generated server exposes @callback definitions for RPCs", %{beam_map: beam_map} do
      server_mod = SimpleGrpc.TypespecTest.Server
      server_bin = Map.fetch!(beam_map, server_mod)

      {:ok, callbacks} = Code.Typespec.fetch_callbacks(server_bin)
      callback_signatures = Enum.map(callbacks, fn {{name, arity}, _ast} -> {name, arity} end)

      assert {:unary_call, 2} in callback_signatures
      assert {:unary_call, 1} in callback_signatures
      assert {:server_streaming_call, 2} in callback_signatures
      assert {:server_streaming_call, 1} in callback_signatures
    end

    test "generated server helper functions have @spec", %{beam_map: beam_map} do
      server_mod = SimpleGrpc.TypespecTest.Server
      server_bin = Map.fetch!(beam_map, server_mod)

      {:ok, specs} = Code.Typespec.fetch_specs(server_bin)
      spec_signatures = Enum.map(specs, fn {{name, arity}, _ast} -> {name, arity} end)

      assert {:grpc_path, 1} in spec_signatures
      assert {:matches_path?, 1} in spec_signatures
      assert {:route_info, 1} in spec_signatures
      assert {:build_request, 1} in spec_signatures or {:build_request, 2} in spec_signatures
      assert {:build_response, 1} in spec_signatures or {:build_response, 2} in spec_signatures
      assert {:dispatch, 2} in spec_signatures or {:dispatch, 3} in spec_signatures
    end
  end
end
